std::vector<int> findCommonElements(const std::vector<int>& arr1, const std::vector<int>& arr2) {
    std::vector<int> result;
    std::vector<int> sortedArr1 = arr1, sortedArr2 = arr2;
    std::sort(sortedArr1.begin(), sortedArr1.end());
    std::sort(sortedArr2.begin(), sortedArr2.end());
    size_t i = 0, j = 0;
    while (i < sortedArr1.size() && j < sortedArr2.size()) {
        if (sortedArr1[i] < sortedArr2[j]) i++;
        else if (sortedArr1[i] > sortedArr2[j]) j++;
        else {
            result.push_back(sortedArr1[i]);
            i++;
            j++;
        }
    }
    return result;
}
