다음은 C++ 코드입니다:

```cpp
#include <iostream>
#include <vector>
#include <unordered_set>

std::vector<int> findCommonElements(const std::vector<int>& arr1, const std::vector<int>& arr2) {
    std::unordered_set<int> elementsSet;
    std::vector<int> result;

    // 첫 번째 배열의 모든 요소를 해시셋에 추가
    for (int elem : arr1) {
        elementsSet.insert(elem);
    }

    // 두 번째 배열에서 공통 요소를 찾음
    for (int elem : arr2) {
        if (elementsSet.find(elem) != elementsSet.end()) {
            result.push_back(elem);
            elementsSet.erase(elem); // 중복을 방지하기 위해 찾은 요소 제거
        }
    }

    return result;
}
```

